import pandas as pd

def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    postings = inputs["postings"].copy()

    # Sort per cursor ORDER BY account_id, post_date, post_seq
    postings = postings.sort_values(
        by=["account_id", "post_date", "post_seq"],
        kind="mergesort"
    ).reset_index(drop=True)

    # Determine validity of each row per TRY/CATCH condition
    qty = postings["qty"]
    price = postings["unit_price"]

    valid = (
        qty.notna() & (qty > 0) &
        price.notna() & (price >= 0)
    )

    postings["_valid"] = valid
    postings["_value"] = qty * price

    posted_rows = []
    reject_rows = []

    for acct, group in postings.groupby("account_id", sort=False):
        tot = 0.0
        rej = 0
        for _, r in group.iterrows():
            if r["_valid"]:
                v = r["_value"]
                tot = tot + v
                posted_rows.append({
                    "account_id": r["account_id"],
                    "post_seq": r["post_seq"],
                    "post_date": r["post_date"],
                    "post_value": v,
                    "running_total": tot
                })
            else:
                rej += 1
        reject_rows.append({
            "account_id": acct,
            "reject_count": rej
        })

    posted_totals = pd.DataFrame(
        posted_rows,
        columns=["account_id", "post_seq", "post_date", "post_value", "running_total"]
    )
    reject_counts = pd.DataFrame(
        reject_rows,
        columns=["account_id", "reject_count"]
    )

    # Type coercion to match expected schema
    if not posted_totals.empty:
        posted_totals["account_id"] = posted_totals["account_id"].astype("int64")
        posted_totals["post_seq"] = posted_totals["post_seq"].astype("int64")
        posted_totals["post_date"] = pd.to_datetime(posted_totals["post_date"])
        posted_totals["post_value"] = posted_totals["post_value"].astype("float64")
        posted_totals["running_total"] = posted_totals["running_total"].astype("float64")
    else:
        posted_totals = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "post_seq": pd.Series(dtype="int64"),
            "post_date": pd.Series(dtype="datetime64[us]"),
            "post_value": pd.Series(dtype="float64"),
            "running_total": pd.Series(dtype="float64"),
        })

    if not reject_counts.empty:
        reject_counts["account_id"] = reject_counts["account_id"].astype("int64")
        reject_counts["reject_count"] = reject_counts["reject_count"].astype("int64")
    else:
        reject_counts = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "reject_count": pd.Series(dtype="int64"),
        })

    return {
        "posted_totals": posted_totals,
        "reject_counts": reject_counts
    }
